    let follower_decided = sim.op(2).get_decided_idx();
    let follower_accepted = sim.op(2).get_accepted_idx();
    let follower_holds_entry = undecided_entry(sim.op(2), 0);
    let leader_still_leader = sim.op(1).get_current_leader() == Some((1, true));
    emit(&format!(
        "{{\"event\":\"lost_accepted_window\",\"steps\":{},\"resend_periods\":{RESEND_PERIODS},\"produced\":\"{}\",\"dropped\":\"{}\",\"leader_decided_idx\":{leader_decided},\"follower_decided_idx\":{follower_decided},\"follower_accepted_idx\":{follower_accepted},\"follower_holds_undecided_entry\":{follower_holds_entry},\"leader_still_stable\":{leader_still_leader}}}",
        RESEND_PERIODS * RESEND_TICKS as usize,
        sim.counts(&sim.produced),
        sim.counts(&sim.dropped)
    ));

    assert_eq!(
        sim.dropped_accepted(),
        1,
        "probe did not drop exactly the follower's Accepted: dropped={}",
        sim.counts(&sim.dropped)
    );
    assert_eq!(
        follower_accepted, 1,
        "follower never accepted the entry, so the quorum premise is missing"
    );
    assert!(
        follower_holds_entry,
        "follower does not hold the entry as Undecided at index 0"
    );
    assert_eq!(
        leader_decided, 0,
        "leader decided even though it never learned of the follower's acceptance"
    );
    assert_eq!(follower_decided, 0, "follower decided without a Decide");
    assert!(
        leader_still_leader,
        "leadership changed during the window, so the non-decision is not the lost receipt"
