    .await;
    emit(&format!(
        "{{\"event\":\"append_notify_endpoint_withheld\",\"node\":{parked_pid},\"per_call_deadline_ms\":300,\"actor_timeout_ms\":1500,\"outer_wait_ms\":4000,\"resolved\":{}}}",
        resolved.is_ok()
    ));
    assert!(
        resolved.is_err(),
        "append_notify on parked node {parked_pid} resolved: {resolved:?}"
    );
}

/// Case 2 (control): same cluster, same capacity, same activity; the only
/// difference is that each node's event stream is drained.
#[tokio::test]
async fn drained_event_stream_keeps_actor_loop_running() {
    let c = spawn_cluster(true).await;
    let leader = wait_for_stable_leader(&c).await;
    assert!(leader.is_some(), "control: no stable leader{}", channel_state(&c));
    let leader = leader.unwrap();
    keep_proposing(&c, leader, 0, EVENT_CAPACITY as u64 * 6);

    let mut alive = 0;
    let deadline = tokio::time::Instant::now() + Duration::from_secs(25);
    while tokio::time::Instant::now() < deadline {
        alive = responsive_nodes(&c, Duration::from_millis(200)).await;
        if alive == c.handles.len() {
            break;
        }
        tokio::time::sleep(Duration::from_millis(100)).await;
    }
    emit(&format!(
        "{{\"event\":\"control_actors_responsive\",\"nodes_answering\":{alive},\"nodes\":3,\"event_capacity\":{EVENT_CAPACITY}}}"
    ));
    assert_eq!(
        alive,
        c.handles.len(),
        "control: some actor loop stopped with a drained event stream{}",
        channel_state(&c)
    );

    let follower = *c.handles.keys().find(|&&p| p != leader).unwrap();
    let idx = match tokio::time::timeout(
        Duration::from_secs(5),
        c.handles[&follower].append_notify(TestEntry(7)),
    )
    .await
    {
        Ok(Ok(idx)) => idx,
        other => panic!("control append_notify: expected Ok(idx), got {other:?}"),
    };
    emit(&format!(
        "{{\"event\":\"control_append_notify\",\"origin\":{follower},\"succeeded\":{},\"idx\":{idx}}}",
        idx >= 1
    ));
    assert!(idx >= 1, "control append_notify returned idx {idx}");
}

/// Case 3: the consequence for the rest of the cluster. Only node 1 reads its event
/// stream, so nodes 2 and 3 reach the bound and park; node 1 stays a healthy actor.
/// Anything that needs those two as a quorum can then no longer be decided.
#[tokio::test]
async fn parked_majority_stops_the_cluster_deciding() {
    let c = spawn_cluster_partial(&[1], 8).await;
    let leader = wait_for_stable_leader(&c).await;
    assert!(leader.is_some(), "setup: no stable leader{}", channel_state(&c));

    // Keep ordinary writes coming so every node observes enough transitions to reach
    // its bound; only the two unread nodes stop after that.
    keep_proposing(&c, leader.unwrap(), 0, 60);
    let mut parked = 0;
    let deadline = tokio::time::Instant::now() + Duration::from_secs(25);
    while tokio::time::Instant::now() < deadline {
        // A parked actor no longer answers commands.
        let answers_2 =
            tokio::time::timeout(Duration::from_millis(250), c.handles[&2].decided_idx())
                .await
                .is_ok();
        let answers_3 =
            tokio::time::timeout(Duration::from_millis(250), c.handles[&3].decided_idx())
                .await
                .is_ok();
        parked = usize::from(!answers_2) + usize::from(!answers_3);
        if parked == 2 {
            break;
        }
        tokio::time::sleep(Duration::from_millis(100)).await;
    }
    let decided_before = tokio::time::timeout(Duration::from_millis(500), c.handles[&1].decided_idx())
        .await
        .expect("node 1 should stay responsive while nodes 2 and 3 are parked");

    // Node 1 is healthy, but it cannot complete a write: the parked nodes never
    // answer, so the entry is never decided. Its own actor does run, so the
    // documented Timeout endpoint is still reachable - what is withheld is progress.
    let res = tokio::time::timeout(
        Duration::from_secs(4),
        c.handles[&1].append_notify_with_timeout(TestEntry(7), Duration::from_millis(300)),
    )
    .await;
    let timeout_reached = matches!(res, Ok(Err(omnipaxos_runtime::AppendError::Timeout)));
    tokio::time::sleep(Duration::from_secs(1)).await;
    let decided_after = tokio::time::timeout(Duration::from_millis(500), c.handles[&1].decided_idx())
        .await
        .expect("node 1 should still be responsive");
    emit(&format!(
        "{{\"event\":\"parked_majority_cluster\",\"nodes_parked\":{parked},\"healthy_node_responsive\":true,\"append_notify_timeout_reached\":{timeout_reached},\"decided_before\":{decided_before},\"decided_after\":{decided_after}}}"
    ));
    assert_eq!(
        parked, 2,
        "setup: nodes 2 and 3 did not both stop answering{}",
        channel_state(&c)
    );
    assert_eq!(
        decided_after, decided_before,
        "the cluster still decided entries although two of three nodes were parked"
    );
}

