fn emit(line: &str) {
    println!("CA_EVENT {line}");
}

async fn deliver_all(
    wire: &Arc<Wire>,
    handles: &std::collections::HashMap<NodeId, OmniPaxosHandle<TestEntry>>,
) -> usize {
    let mut delivered = 0;
    loop {
        let msg = wire.queue.lock().unwrap().pop_front();
        let Some(msg) = msg else { break };
